/**
 * @fileoverview TPMJS registry client for discovering and fetching MCP tool manifests.
 *
 * Communicates with the TPMJS registry (tpmjs.com) to search for tools,
 * fetch individual tool manifests, and resolve package metadata.
 *
 * @module tools/tpmjs_client
 */

import { logger } from '../utils/logger.js';

// ============================================================================
// Types
// ============================================================================

/** A single parameter in a TPMJS tool manifest. */
export interface TpmjsToolParameter {
  name: string;
  type: 'string' | 'number' | 'boolean';
  description: string;
  required?: boolean;
  default?: unknown;
}

/** MCP server transport configuration from a TPMJS manifest. */
export interface TpmjsMcpConfig {
  /** Transport type: stdio, sse, or streamable-http */
  transport: 'stdio' | 'sse' | 'streamable-http';
  /** Command to launch (for stdio transport) */
  command?: string;
  /** Arguments for the command */
  args?: string[];
  /** URL endpoint (for sse/streamable-http transport) */
  url?: string;
  /** Environment variables required by the MCP server */
  env?: Record<string, string>;
}

/** A tool definition within a TPMJS package manifest. */
export interface TpmjsToolDefinition {
  name: string;
  description: string;
  parameters: TpmjsToolParameter[];
}

/** Full TPMJS package manifest returned by the registry. */
export interface TpmjsManifest {
  /** Package name (e.g., "@tpmjs/discord-read") */
  name: string;
  /** Package version */
  version: string;
  /** Human-readable description */
  description: string;
  /** Package author */
  author?: string;
  /** License identifier */
  license?: string;
  /** MCP server configuration */
  mcp?: TpmjsMcpConfig;
  /** Tools exposed by this package */
  tools: TpmjsToolDefinition[];
  /** npm package name for installation (if stdio transport) */
  package?: string;
  /** Keywords for search */
  keywords?: string[];
}

/** Search result item from the TPMJS registry. */
export interface TpmjsSearchResult {
  name: string;
  description: string;
  version: string;
  author?: string;
  keywords?: string[];
  downloads?: number;
}

/** Response shape from the TPMJS search endpoint. */
interface TpmjsSearchResponse {
  results: TpmjsSearchResult[];
  total: number;
}

/** Response shape from the TPMJS manifest endpoint. */
type TpmjsManifestResponse = TpmjsManifest;

// ============================================================================
// Client
// ============================================================================

const DEFAULT_REGISTRY_URL = 'https://registry.tpmjs.com';
const REQUEST_TIMEOUT_MS = 15_000;

export class TpmjsClient {
  private readonly registryUrl: string;

  constructor(registryUrl?: string) {
    this.registryUrl = (registryUrl ?? DEFAULT_REGISTRY_URL).replace(/\/+$/, '');
  }

  /**
   * Search the TPMJS registry for tools matching a query.
   */
  async search(query: string, limit = 20): Promise<TpmjsSearchResult[]> {
    const url = `${this.registryUrl}/api/v1/search?q=${encodeURIComponent(query)}&limit=${limit}`;
    logger.info(`TPMJS: searching registry`, { query, limit });

    try {
      const response = await this.fetch(url);

      if (!response.ok) {
        logger.warn(`TPMJS search failed: HTTP ${response.status}`);
        return [];
      }

      const data = (await response.json()) as TpmjsSearchResponse;
      return data.results ?? [];
    } catch (error) {
      logger.error('TPMJS search error', { error, query });
      return [];
    }
  }

  /**
   * Fetch the full manifest for a specific TPMJS package.
   */
  async getManifest(packageName: string): Promise<TpmjsManifest | null> {
    const encoded = encodeURIComponent(packageName);
    const url = `${this.registryUrl}/api/v1/packages/${encoded}`;
    logger.info(`TPMJS: fetching manifest`, { packageName });

    try {
      const response = await this.fetch(url);

      if (response.status === 404) {
        logger.warn(`TPMJS package not found: ${packageName}`);
        return null;
      }

      if (!response.ok) {
        logger.warn(`TPMJS manifest fetch failed: HTTP ${response.status}`);
        return null;
      }

      const data = (await response.json()) as TpmjsManifestResponse;
      return data;
    } catch (error) {
      logger.error('TPMJS manifest fetch error', { error, packageName });
      return null;
    }
  }

  /**
   * Fetch manifests for multiple packages in parallel.
   */
  async getManifests(packageNames: string[]): Promise<Map<string, TpmjsManifest>> {
    const results = new Map<string, TpmjsManifest>();
    const settled = await Promise.allSettled(
      packageNames.map(async (name) => {
        const manifest = await this.getManifest(name);
        if (manifest) results.set(name, manifest);
      })
    );

    for (const result of settled) {
      if (result.status === 'rejected') {
        logger.warn('TPMJS manifest batch fetch partial failure', { reason: result.reason });
      }
    }

    return results;
  }

  /**
   * Check if the registry is reachable.
   */
  async ping(): Promise<boolean> {
    try {
      const response = await this.fetch(`${this.registryUrl}/api/v1/health`);
      return response.ok;
    } catch {
      return false;
    }
  }

  private async fetch(url: string): Promise<Response> {
    return globalThis.fetch(url, {
      headers: {
        'Accept': 'application/json',
        'User-Agent': 'fetch-bridge/tpmjs-client',
      },
      signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
    });
  }
}

// ============================================================================
// Singleton
// ============================================================================

let clientInstance: TpmjsClient | undefined;

export function getTpmjsClient(registryUrl?: string): TpmjsClient {
  if (!clientInstance) {
    clientInstance = new TpmjsClient(registryUrl);
  }
  return clientInstance;
}

/** Reset the singleton (used in tests). */
export function resetTpmjsClient(): void {
  clientInstance = undefined;
}

