  1→/**
  2→ * @fileoverview TPMJS tool loader — resolves TPMJS manifests into runtime tools.
  3→ *
  4→ * Handles:
  5→ * - Loading tool lists from fetch.config.json
  6→ * - Resolving TPMJS manifests into OrchestratorTool registrations
  7→ * - MCP transport setup (stdio command spawning, SSE/HTTP endpoints)
  8→ * - Installing npm packages for stdio-based MCP servers
  9→ *
 10→ * @module tools/tpmjs_loader
 11→ */
 12→
 13→import { z } from 'zod';
 14→import { exec } from 'child_process';
 15→import util from 'util';
 16→import fs from 'fs/promises';
 17→import path from 'path';
 18→import { logger } from '../utils/logger.js';
 19→import { DangerLevel } from './types.js';
 20→import type { OrchestratorTool } from './registry.js';
 21→import {
 22→  getTpmjsClient,
 23→  type TpmjsManifest,
 24→  type TpmjsToolDefinition,
 25→  type TpmjsToolParameter,
 26→  type TpmjsMcpConfig,
 27→} from './tpmjs_client.js';
 28→import { DATA_DIR } from '../config/paths.js';
 29→
 30→const execPromise = util.promisify(exec);
 31→
 32→// ============================================================================
 33→// fetch.config.json Schema
 34→// ============================================================================
 35→
 36→const fetchConfigSchema = z.object({
 37→  tools: z.array(z.string()).default([]),
 38→}).passthrough();
 39→
 40→export interface FetchConfig {
 41→  tools: string[];
 42→}
 43→
 44→// ============================================================================
 45→// Installed Package Tracking
 46→// ============================================================================
 47→
 48→/** Directory where TPMJS npm packages are installed locally. */
 49→const TPMJS_INSTALL_DIR = path.join(DATA_DIR, 'tpmjs_modules');
 50→
 51→/** Cache of loaded manifests to avoid redundant fetches. */
 52→const manifestCache = new Map<string, TpmjsManifest>();
 53→
 54→// ============================================================================
 55→// Config Loading
 56→// ============================================================================
 57→
 58→/**
 59→ * Load and parse the fetch.config.json from the project root or data dir.
 60→ */
 61→export async function loadFetchConfig(configPath?: string): Promise<FetchConfig> {
 62→  const candidates = configPath
 63→    ? [configPath]
 64→    : [
 65→        path.join(process.cwd(), 'fetch.config.json'),
 66→        path.join(DATA_DIR, 'fetch.config.json'),
 67→      ];
 68→
 69→  for (const candidate of candidates) {
 70→    try {
 71→      const content = await fs.readFile(candidate, 'utf-8');
 72→      const parsed = JSON.parse(content);
 73→      const validated = fetchConfigSchema.safeParse(parsed);
 74→
 75→      if (validated.success) {
 76→        logger.info(`TPMJS: loaded config from ${candidate}`, { tools: validated.data.tools });
 77→        return validated.data;
 78→      }
 79→
 80→      logger.warn(`TPMJS: invalid config at ${candidate}`, {
 81→        issues: validated.error.issues,
 82→      });
 83→    } catch {
 84→      // File not found or unreadable — try next candidate
 85→    }
 86→  }
 87→
 88→  logger.debug('TPMJS: no fetch.config.json found, using empty tool list');
 89→  return { tools: [] };
 90→}
 91→
 92→// ============================================================================
 93→// Tool Resolution
 94→// ============================================================================
 95→
 96→/**
 97→ * Resolve a list of TPMJS package names into OrchestratorTool registrations.
 98→ *
 99→ * For each package:
100→ * 1. Fetch the manifest from the TPMJS registry
101→ * 2. If stdio transport, ensure the npm package is installed locally
102→ * 3. Convert each tool definition into an OrchestratorTool with a handler
103→ */
104→export async function resolveTools(
105→  packageNames: string[],
106→  registryUrl?: string,
107→): Promise<OrchestratorTool[]> {
108→  if (packageNames.length === 0) return [];
109→
110→  const client = getTpmjsClient(registryUrl);
111→  const tools: OrchestratorTool[] = [];
112→
113→  const manifests = await client.getManifests(packageNames);
114→
115→  for (const [pkgName, manifest] of manifests) {
116→    try {
117→      manifestCache.set(pkgName, manifest);
118→
119→      // Ensure stdio packages are installed
120→      if (manifest.mcp?.transport === 'stdio' && manifest.package) {
121→        await ensurePackageInstalled(manifest.package);
122→      }
123→
124→      // Convert each tool definition to an OrchestratorTool
125→      for (const toolDef of manifest.tools) {
126→        const resolved = buildOrchestratorTool(toolDef, manifest);
127→        if (resolved) {
128→          tools.push(resolved);
129→        }
130→      }
131→
132→      logger.info(`TPMJS: resolved ${manifest.tools.length} tools from ${pkgName}`);
133→    } catch (error) {
134→      logger.error(`TPMJS: failed to resolve tools from ${pkgName}`, { error });
135→    }
136→  }
137→
138→  return tools;
139→}
140→
141→/**
142→ * Resolve a single package by name and return its tools.
143→ */
144→export async function resolveSinglePackage(
145→  packageName: string,
146→  registryUrl?: string,
147→): Promise<OrchestratorTool[]> {
148→  return resolveTools([packageName], registryUrl);
149→}
150→
151→// ============================================================================
152→// Tool Building
153→// ============================================================================
154→
155→function buildOrchestratorTool(
156→  toolDef: TpmjsToolDefinition,
157→  manifest: TpmjsManifest,
158→): OrchestratorTool | null {
159→  try {
160→    const schema = buildZodSchema(toolDef.parameters);
161→    const handler = buildHandler(toolDef, manifest.mcp);
162→
163→    return {
164→      name: toolDef.name,
165→      description: `[TPMJS: ${manifest.name}] ${toolDef.description}`,
166→      schema,
167→      handler,
168→      danger: DangerLevel.MODERATE,
169→      isCustom: true,
170→    };
171→  } catch (error) {
172→    logger.error(`TPMJS: failed to build tool ${toolDef.name}`, { error });
173→    return null;
174→  }
175→}
176→
177→function buildZodSchema(parameters: TpmjsToolParameter[]): z.ZodSchema {
178→  const shape: Record<string, z.ZodTypeAny> = {};
179→
180→  for (const param of parameters) {
181→    let validator: z.ZodTypeAny;
182→
183→    switch (param.type) {
184→      case 'number': validator = z.number(); break;
185→      case 'boolean': validator = z.boolean(); break;
186→      case 'string': default: validator = z.string(); break;
187→    }
188→
189→    if (param.description) validator = validator.describe(param.description);
190→    if (!param.required && param.default === undefined) validator = validator.optional();
191→    if (param.default !== undefined) validator = validator.default(param.default);
192→
193→    shape[param.name] = validator;
194→  }
195→
196→  return z.object(shape);
197→}
198→
199→function buildHandler(
200→  toolDef: TpmjsToolDefinition,
201→  mcpConfig?: TpmjsMcpConfig,
202→) {
203→  if (!mcpConfig) {
204→    // No MCP config — return a stub that explains the tool needs configuration
205→    return async () => ({
206→      success: false,
207→      output: `Tool '${toolDef.name}' has no MCP configuration. It may require manual setup.`,
208→      duration: 0,
209→    });
210→  }
211→
212→  switch (mcpConfig.transport) {
213→    case 'stdio':
214→      return buildStdioHandler(toolDef, mcpConfig);
215→    case 'sse':
216→    case 'streamable-http':
217→      return buildHttpHandler(toolDef, mcpConfig);
218→    default:
219→      return async () => ({
220→        success: false,
221→        output: `Unsupported MCP transport: ${mcpConfig.transport}`,
222→        duration: 0,
223→      });
224→  }
225→}
226→
227→function buildStdioHandler(toolDef: TpmjsToolDefinition, mcpConfig: TpmjsMcpConfig) {
228→  return async (input: unknown) => {
229→    const start = Date.now();
230→    const params = input as Record<string, unknown>;
231→
232→    try {
233→      const command = mcpConfig.command ?? 'npx';
234→      const args = mcpConfig.args ?? [];
235→
236→      // Build the MCP JSON-RPC request for tool invocation
237→      const mcpRequest = JSON.stringify({
238→        jsonrpc: '2.0',
239→        id: 1,
240→        method: 'tools/call',
241→        params: {
242→          name: toolDef.name,
243→          arguments: params,
244→        },
245→      });
246→
247→      const fullCommand = [command, ...args].join(' ');
248→      const env = { ...process.env, ...(mcpConfig.env ?? {}) };
249→
250→      const { stdout, stderr } = await execPromise(
251→        `echo '${mcpRequest.replace(/'/g, "'\\''")}' | ${fullCommand}`,
252→        {
253→          env,
254→          cwd: TPMJS_INSTALL_DIR,
255→          timeout: 30_000,
256→        },
257→      );
258→
259→      // Try to parse MCP JSON-RPC response
260→      try {
261→        const response = JSON.parse(stdout);
262→        if (response.result) {
263→          const content = response.result.content;
264→          if (Array.isArray(content)) {
265→            const text = content
266→              .filter((c: { type: string }) => c.type === 'text')
267→              .map((c: { text: string }) => c.text)
268→              .join('\n');
269→            return { success: true, output: text || stdout, duration: Date.now() - start };
270→          }
271→          return { success: true, output: JSON.stringify(response.result), duration: Date.now() - start };
272→        }
273→        if (response.error) {
274→          return { success: false, output: response.error.message ?? JSON.stringify(response.error), duration: Date.now() - start };
275→        }
276→      } catch {
277→        // Not JSON — return raw output
278→      }
279→
280→      return {
281→        success: true,
282→        output: (stdout || stderr || 'Command executed').slice(0, 100_000),
283→        duration: Date.now() - start,
284→      };
285→    } catch (error) {
286→      const err = error as { message?: string; stderr?: string };
287→      return {
288→        success: false,
289→        output: '',
290→        error: err.message || err.stderr || 'TPMJS stdio execution failed',
291→        duration: Date.now() - start,
292→      };
293→    }
294→  };
295→}
296→
297→function buildHttpHandler(toolDef: TpmjsToolDefinition, mcpConfig: TpmjsMcpConfig) {
298→  return async (input: unknown) => {
299→    const start = Date.now();
300→    const params = input as Record<string, unknown>;
301→
302→    if (!mcpConfig.url) {
303→      return {
304→        success: false,
305→        output: `Tool '${toolDef.name}' requires a URL for ${mcpConfig.transport} transport`,
306→        duration: 0,
307→      };
308→    }
309→
310→    try {
311→      const mcpRequest = {
312→        jsonrpc: '2.0',
313→        id: 1,
314→        method: 'tools/call',
315→        params: {
316→          name: toolDef.name,
317→          arguments: params,
318→        },
319→      };
320→
321→      const response = await globalThis.fetch(mcpConfig.url, {
322→        method: 'POST',
323→        headers: {
324→          'Content-Type': 'application/json',
325→          'Accept': 'application/json',
326→        },
327→        body: JSON.stringify(mcpRequest),
328→        signal: AbortSignal.timeout(30_000),
329→      });
330→
331→      if (!response.ok) {
332→        return {
333→          success: false,
334→          output: `MCP HTTP error: ${response.status} ${response.statusText}`,
335→          duration: Date.now() - start,
336→        };
337→      }
338→
339→      const data = await response.json() as { result?: { content?: Array<{ type: string; text: string }> }; error?: { message?: string } };
340→
341→      if (data.result) {
342→        const content = data.result.content;
343→        if (Array.isArray(content)) {
344→          const text = content
