/**
 * @fileoverview TPMJS tool loader — resolves TPMJS manifests into runtime tools.
 *
 * Handles:
 * - Loading tool lists from fetch.config.json
 * - Resolving TPMJS manifests into OrchestratorTool registrations
 * - MCP transport setup (stdio command spawning, SSE/HTTP endpoints)
 * - Installing npm packages for stdio-based MCP servers
 *
 * @module tools/tpmjs_loader
 */

import { z } from 'zod';
import { exec } from 'child_process';
import util from 'util';
import fs from 'fs/promises';
import path from 'path';
import { logger } from '../utils/logger.js';
import { DangerLevel } from './types.js';
import type { OrchestratorTool } from './registry.js';
import {
  getTpmjsClient,
  type TpmjsManifest,
  type TpmjsToolDefinition,
  type TpmjsToolParameter,
  type TpmjsMcpConfig,
} from './tpmjs_client.js';
import { DATA_DIR } from '../config/paths.js';

const execPromise = util.promisify(exec);

// ============================================================================
// fetch.config.json Schema
// ============================================================================

const fetchConfigSchema = z.object({
  tools: z.array(z.string()).default([]),
}).passthrough();

export interface FetchConfig {
  tools: string[];
}

// ============================================================================
// Installed Package Tracking
// ============================================================================

/** Directory where TPMJS npm packages are installed locally. */
const TPMJS_INSTALL_DIR = path.join(DATA_DIR, 'tpmjs_modules');

/** Cache of loaded manifests to avoid redundant fetches. */
const manifestCache = new Map<string, TpmjsManifest>();

// ============================================================================
// Config Loading
// ============================================================================

/**
 * Load and parse the fetch.config.json from the project root or data dir.
 */
export async function loadFetchConfig(configPath?: string): Promise<FetchConfig> {
  const candidates = configPath
    ? [configPath]
    : [
        path.join(process.cwd(), 'fetch.config.json'),
        path.join(DATA_DIR, 'fetch.config.json'),
      ];

  for (const candidate of candidates) {
    try {
      const content = await fs.readFile(candidate, 'utf-8');
      const parsed = JSON.parse(content);
      const validated = fetchConfigSchema.safeParse(parsed);

      if (validated.success) {
        logger.info(`TPMJS: loaded config from ${candidate}`, { tools: validated.data.tools });
        return validated.data;
      }

      logger.warn(`TPMJS: invalid config at ${candidate}`, {
        issues: validated.error.issues,
      });
    } catch {
      // File not found or unreadable — try next candidate
    }
  }

  logger.debug('TPMJS: no fetch.config.json found, using empty tool list');
  return { tools: [] };
}

// ============================================================================
// Tool Resolution
// ============================================================================

/**
 * Resolve a list of TPMJS package names into OrchestratorTool registrations.
 *
 * For each package:
 * 1. Fetch the manifest from the TPMJS registry
 * 2. If stdio transport, ensure the npm package is installed locally
 * 3. Convert each tool definition into an OrchestratorTool with a handler
 */
export async function resolveTools(
  packageNames: string[],
  registryUrl?: string,
): Promise<OrchestratorTool[]> {
  if (packageNames.length === 0) return [];

  const client = getTpmjsClient(registryUrl);
  const tools: OrchestratorTool[] = [];

  const manifests = await client.getManifests(packageNames);

  for (const [pkgName, manifest] of manifests) {
    try {
      manifestCache.set(pkgName, manifest);

      // Ensure stdio packages are installed
      if (manifest.mcp?.transport === 'stdio' && manifest.package) {
        await ensurePackageInstalled(manifest.package);
      }

      // Convert each tool definition to an OrchestratorTool
      for (const toolDef of manifest.tools) {
        const resolved = buildOrchestratorTool(toolDef, manifest);
        if (resolved) {
          tools.push(resolved);
        }
      }

      logger.info(`TPMJS: resolved ${manifest.tools.length} tools from ${pkgName}`);
    } catch (error) {
      logger.error(`TPMJS: failed to resolve tools from ${pkgName}`, { error });
    }
  }

  return tools;
}

/**
 * Resolve a single package by name and return its tools.
 */
export async function resolveSinglePackage(
  packageName: string,
  registryUrl?: string,
): Promise<OrchestratorTool[]> {
  return resolveTools([packageName], registryUrl);
}

// ============================================================================
// Tool Building
// ============================================================================

function buildOrchestratorTool(
  toolDef: TpmjsToolDefinition,
  manifest: TpmjsManifest,
): OrchestratorTool | null {
  try {
    const schema = buildZodSchema(toolDef.parameters);
    const handler = buildHandler(toolDef, manifest.mcp);

    return {
      name: toolDef.name,
      description: `[TPMJS: ${manifest.name}] ${toolDef.description}`,
      schema,
      handler,
      danger: DangerLevel.MODERATE,
      isCustom: true,
    };
  } catch (error) {
    logger.error(`TPMJS: failed to build tool ${toolDef.name}`, { error });
    return null;
  }
}

function buildZodSchema(parameters: TpmjsToolParameter[]): z.ZodSchema {
  const shape: Record<string, z.ZodTypeAny> = {};

  for (const param of parameters) {
    let validator: z.ZodTypeAny;

    switch (param.type) {
      case 'number': validator = z.number(); break;
      case 'boolean': validator = z.boolean(); break;
      case 'string': default: validator = z.string(); break;
    }

    if (param.description) validator = validator.describe(param.description);
    if (!param.required && param.default === undefined) validator = validator.optional();
    if (param.default !== undefined) validator = validator.default(param.default);

    shape[param.name] = validator;
  }

  return z.object(shape);
}

function buildHandler(
  toolDef: TpmjsToolDefinition,
  mcpConfig?: TpmjsMcpConfig,
) {
  if (!mcpConfig) {
    // No MCP config — return a stub that explains the tool needs configuration
    return async () => ({
      success: false,
      output: `Tool '${toolDef.name}' has no MCP configuration. It may require manual setup.`,
      duration: 0,
    });
  }

  switch (mcpConfig.transport) {
    case 'stdio':
      return buildStdioHandler(toolDef, mcpConfig);
    case 'sse':
    case 'streamable-http':
      return buildHttpHandler(toolDef, mcpConfig);
    default:
      return async () => ({
        success: false,
        output: `Unsupported MCP transport: ${mcpConfig.transport}`,
        duration: 0,
      });
  }
}

function buildStdioHandler(toolDef: TpmjsToolDefinition, mcpConfig: TpmjsMcpConfig) {
  return async (input: unknown) => {
    const start = Date.now();
    const params = input as Record<string, unknown>;

    try {
      const command = mcpConfig.command ?? 'npx';
      const args = mcpConfig.args ?? [];

      // Build the MCP JSON-RPC request for tool invocation
      const mcpRequest = JSON.stringify({
        jsonrpc: '2.0',
        id: 1,
        method: 'tools/call',
        params: {
          name: toolDef.name,
          arguments: params,
        },
      });

      const fullCommand = [command, ...args].join(' ');
      const env = { ...process.env, ...(mcpConfig.env ?? {}) };

      const { stdout, stderr } = await execPromise(
        `echo '${mcpRequest.replace(/'/g, "'\\''")}' | ${fullCommand}`,
        {
          env,
          cwd: TPMJS_INSTALL_DIR,
          timeout: 30_000,
        },
      );

      // Try to parse MCP JSON-RPC response
      try {
        const response = JSON.parse(stdout);
        if (response.result) {
          const content = response.result.content;
          if (Array.isArray(content)) {
            const text = content
              .filter((c: { type: string }) => c.type === 'text')
              .map((c: { text: string }) => c.text)
              .join('\n');
            return { success: true, output: text || stdout, duration: Date.now() - start };
          }
          return { success: true, output: JSON.stringify(response.result), duration: Date.now() - start };
        }
        if (response.error) {
          return { success: false, output: response.error.message ?? JSON.stringify(response.error), duration: Date.now() - start };
        }
      } catch {
        // Not JSON — return raw output
      }

      return {
        success: true,
        output: (stdout || stderr || 'Command executed').slice(0, 100_000),
        duration: Date.now() - start,
      };
    } catch (error) {
      const err = error as { message?: string; stderr?: string };
      return {
        success: false,
        output: '',
        error: err.message || err.stderr || 'TPMJS stdio execution failed',
        duration: Date.now() - start,
      };
    }
  };
}

function buildHttpHandler(toolDef: TpmjsToolDefinition, mcpConfig: TpmjsMcpConfig) {
  return async (input: unknown) => {
    const start = Date.now();
    const params = input as Record<string, unknown>;

    if (!mcpConfig.url) {
      return {
        success: false,
        output: `Tool '${toolDef.name}' requires a URL for ${mcpConfig.transport} transport`,
        duration: 0,
      };
    }

    try {
      const mcpRequest = {
        jsonrpc: '2.0',
        id: 1,
        method: 'tools/call',
        params: {
          name: toolDef.name,
          arguments: params,
        },
      };

      const response = await globalThis.fetch(mcpConfig.url, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Accept': 'application/json',
        },
        body: JSON.stringify(mcpRequest),
        signal: AbortSignal.timeout(30_000),
      });

      if (!response.ok) {
        return {
          success: false,
          output: `MCP HTTP error: ${response.status} ${response.statusText}`,
          duration: Date.now() - start,
        };
      }

      const data = await response.json() as { result?: { content?: Array<{ type: string; text: string }> }; error?: { message?: string } };

      if (data.result) {
        const content = data.result.content;
        if (Array.isArray(content)) {
          const text = content
            .filter((c) => c.type === 'text')
            .map((c) => c.text)
            .join('\n');
          return { success: true, output: text, duration: Date.now() - start };
        }
        return { success: true, output: JSON.stringify(data.result), duration: Date.now() - start };
      }

      if (data.error) {
        return {
          success: false,
          output: data.error.message ?? JSON.stringify(data.error),
          duration: Date.now() - start,
        };
      }

      return { success: true, output: JSON.stringify(data), duration: Date.now() - start };
    } catch (error) {
      return {
        success: false,
        output: '',
        error: error instanceof Error ? error.message : 'TPMJS HTTP execution failed',
        duration: Date.now() - start,
      };
    }
  };
}

// ============================================================================
// Package Installation
// ============================================================================

async function ensurePackageInstalled(packageName: string): Promise<void> {
  // Create install dir if needed
  try {
    await fs.mkdir(TPMJS_INSTALL_DIR, { recursive: true });
  } catch {
    // Already exists
  }

  // Check if package.json exists in install dir
  const pkgJsonPath = path.join(TPMJS_INSTALL_DIR, 'package.json');
  try {
    await fs.access(pkgJsonPath);
  } catch {
    await fs.writeFile(pkgJsonPath, JSON.stringify({ name: 'tpmjs-tools', private: true }, null, 2));
  }

  // Check if already installed
  const nodeModulesPath = path.join(TPMJS_INSTALL_DIR, 'node_modules', ...packageName.split('/'));
  try {
    await fs.access(nodeModulesPath);
    logger.debug(`TPMJS: package already installed: ${packageName}`);
    return;
  } catch {
    // Not installed — proceed
  }

  logger.info(`TPMJS: installing package ${packageName}`);
  try {
    await execPromise(`npm install --save ${packageName}`, {
      cwd: TPMJS_INSTALL_DIR,
      timeout: 60_000,
    });
    logger.info(`TPMJS: installed ${packageName}`);
  } catch (error) {
    logger.error(`TPMJS: failed to install ${packageName}`, { error });
    throw error;
  }
}

// ============================================================================
// Public API
// ============================================================================

/** Get the cached manifest for a package (if previously resolved). */
export function getCachedManifest(packageName: string): TpmjsManifest | undefined {
  return manifestCache.get(packageName);
}

/** Clear the manifest cache (used in tests). */
export function clearManifestCache(): void {
  manifestCache.clear();
}

