import { describe, it, expect } from 'vitest';
import {
  formatForPlatform,
  chunkForPlatform,
  formatAndChunk,
  getMaxLength,
} from '../../src/bridge/format.js';

describe('bridge/format', () => {
  describe('formatForPlatform', () => {
    it('converts **bold** to *bold* for WhatsApp', () => {
      expect(formatForPlatform('**hello**', 'whatsapp')).toBe('*hello*');
    });

    it('converts ~~strike~~ to ~strike~ for WhatsApp', () => {
      expect(formatForPlatform('~~gone~~', 'whatsapp')).toBe('~gone~');
    });

    it('converts **bold** to *bold* for Slack', () => {
      expect(formatForPlatform('**hello**', 'slack')).toBe('*hello*');
    });

    it('converts **bold** to *bold* for Telegram', () => {
      expect(formatForPlatform('**hello**', 'telegram')).toBe('*hello*');
    });

    it('passes Discord markdown through unchanged', () => {
      const text = '**bold** *italic* ~~strike~~ `code`';
      expect(formatForPlatform(text, 'discord')).toBe(text);
    });

    it('preserves _italic_ for all platforms', () => {
      for (const platform of ['whatsapp', 'slack', 'telegram', 'discord'] as const) {
        expect(formatForPlatform('_italic_', platform)).toBe('_italic_');
      }
    });

    it('preserves ```code blocks``` for all platforms', () => {
      const code = '```\nconst x = 1;\n```';
      for (const platform of ['whatsapp', 'slack', 'telegram', 'discord'] as const) {
        expect(formatForPlatform(code, platform)).toBe(code);
      }
    });
  });

  describe('chunkForPlatform', () => {
    it('returns single chunk for short messages', () => {
      const result = chunkForPlatform('hello world', 'discord');
      expect(result).toEqual(['hello world']);
    });

    it('splits long messages for Discord (2000 char limit)', () => {
      const longText = 'A'.repeat(3000);
      const chunks = chunkForPlatform(longText, 'discord');
      expect(chunks.length).toBeGreaterThan(1);
      for (const chunk of chunks) {
        expect(chunk.length).toBeLessThanOrEqual(2000);
      }
    });

    it('splits on paragraph boundaries when possible', () => {
      const text = 'First paragraph.\n\n' + 'A'.repeat(1990);
      const chunks = chunkForPlatform(text, 'discord');
      expect(chunks[0]).toBe('First paragraph.');
    });

    it('splits on newline boundaries when no paragraph break', () => {
      const text = 'Line one.\n' + 'B'.repeat(1995);
      const chunks = chunkForPlatform(text, 'discord');
      expect(chunks[0]).toBe('Line one.');
    });
  });

  describe('formatAndChunk', () => {
    it('formats then chunks in one call', () => {
      const result = formatAndChunk('**hello**', 'whatsapp');
      expect(result).toEqual(['*hello*']);
    });
  });

  describe('getMaxLength', () => {
    it('returns correct limits per platform', () => {
      expect(getMaxLength('whatsapp')).toBe(4096);
      expect(getMaxLength('slack')).toBe(3000);
      expect(getMaxLength('telegram')).toBe(4096);
      expect(getMaxLength('discord')).toBe(2000);
    });
  });
});

