import { describe, it, expect, beforeEach } from 'vitest';
import {
  registerBridge,
  unregisterBridge,
  getBridge,
  getAllBridges,
  sendViaBridge,
} from '../../src/bridge/interface.js';
import type { MessagingBridge, BridgeEvents, SendOptions, Platform } from '../../src/bridge/interface.js';

/** Minimal mock bridge for testing the registry. */
function createMockBridge(platform: Platform, ready = true): MessagingBridge & { sentMessages: Array<{ targetId: string; text: string; options?: SendOptions }> } {
  const sentMessages: Array<{ targetId: string; text: string; options?: SendOptions }> = [];
  return {
    platform,
    sentMessages,
    async initialize() {},
    isReady: () => ready,
    async sendMessage(targetId: string, text: string, options?: SendOptions) {
      sentMessages.push({ targetId, text, options });
      return `msg-${sentMessages.length}`;
    },
    on<K extends keyof BridgeEvents>(_event: K, _listener: BridgeEvents[K]) {},
    off<K extends keyof BridgeEvents>(_event: K, _listener: BridgeEvents[K]) {},
    async destroy() {},
  };
}

describe('bridge/interface - Bridge Registry', () => {
  beforeEach(() => {
    // Clean up registry between tests
    for (const p of ['whatsapp', 'slack', 'telegram', 'discord'] as Platform[]) {
      unregisterBridge(p);
    }
  });

  it('registers and retrieves a bridge by platform', () => {
    const bridge = createMockBridge('slack');
    registerBridge(bridge);

    expect(getBridge('slack')).toBe(bridge);
    expect(getBridge('discord')).toBeUndefined();
  });

  it('unregisters a bridge', () => {
    const bridge = createMockBridge('telegram');
    registerBridge(bridge);
    expect(getBridge('telegram')).toBe(bridge);

    unregisterBridge('telegram');
    expect(getBridge('telegram')).toBeUndefined();
  });

  it('getAllBridges returns all registered bridges', () => {
    const slack = createMockBridge('slack');
    const discord = createMockBridge('discord');
    registerBridge(slack);
    registerBridge(discord);

    const all = getAllBridges();
    expect(all).toHaveLength(2);
    expect(all).toContain(slack);
    expect(all).toContain(discord);
  });

  it('sendViaBridge sends through the correct bridge', async () => {
    const slack = createMockBridge('slack');
    registerBridge(slack);

    const msgId = await sendViaBridge('slack', 'C123', 'hello');
    expect(msgId).toBe('msg-1');
    expect(slack.sentMessages).toHaveLength(1);
    expect(slack.sentMessages[0]).toEqual({
      targetId: 'C123',
      text: 'hello',
      options: undefined,
    });
  });

  it('sendViaBridge returns undefined for unregistered platform', async () => {
    const result = await sendViaBridge('discord', 'channel', 'hello');
    expect(result).toBeUndefined();
  });

  it('sendViaBridge returns undefined when bridge is not ready', async () => {
    const bridge = createMockBridge('slack', false);
    registerBridge(bridge);

    const result = await sendViaBridge('slack', 'C123', 'hello');
    expect(result).toBeUndefined();
  });

  it('replaces a bridge when re-registered', () => {
    const first = createMockBridge('slack');
    const second = createMockBridge('slack');
    registerBridge(first);
    registerBridge(second);

    expect(getBridge('slack')).toBe(second);
    expect(getAllBridges()).toHaveLength(1);
  });
});

